diff --git a/py/mpz.c b/py/mpz.c
index 1732373..8b0737a 100644
--- a/py/mpz.c
+++ b/py/mpz.c
@@ -1711,13 +1711,13 @@ STATIC void mpz_format_base_n(mp_int_t *z, int base, char *buf, size_t buf_len,
         }
     }

-    // Add thousands separators
-    if (thousands_sep != '\0') {
-        size_t pos = 0;
-        for (size_t i = 0; i < len; ++i) {
-            if (i > 0 && (len - i) % 3 == 0) {
-                buf[pos++] = thousands_sep;
-            }
+    // Add thousands separators before the done-checking loop
+    if (thousands_sep != '\0') {
+        for (size_t i = 0; i < len; ++i) {
+            if (i > 0 && (len - i) % 3 == 0) {
+                buf[i] = thousands_sep;
+            }
+            buf[i + 1] = buf[i];
+        }
+        len += (len - 1) / 3;
+    }
+
+    // Done-checking loop
+    for (size_t i = 0; i < len; ++i) {
+        if (buf[i] == thousands_sep) {
+            continue;
+        }
+        if (buf[i] == '0' && i == 0 && !leading_zero) {
+            continue;
+        }
+        leading_zero = false;
+        buf[pos++] = buf[i];
+    }
